// Lesson 03: the 1.9" IPS display (ST7789 driver, 170 x 320 pixels, SPI).
//
// Wiring (module label -> ESP32-S3), all set in kit/include/pins.h:
//   GND -> GND      VCC -> 3V3
//   SCL -> 12       SDA -> 11      RES -> 8
//   DC  -> 9        CS  -> 10      BLK -> 7
//
// What happens:
//   1. A colour check: red, green, blue bars. If the colours look wrong, see the notes below.
//   2. A live "bench scope": a sine wave sweeping across the screen with uptime and frame rate.
//
// New ideas in this lesson:
//   - SPI: a fast 4-wire bus. The ESP32 clocks bits out on SDA while toggling SCL.
//   - A frame buffer: we draw the whole picture in PSRAM first, then send it in one go,
//     so the screen never shows a half-drawn frame (no flicker).
#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>
#include <Arduino.h>
#include <SPI.h>

#include "pins.h"

namespace {

constexpr int16_t kW = 320;  // Landscape: rotation 1 turns the 170x320 panel sideways.
constexpr int16_t kH = 170;
constexpr uint32_t kSpiHz = 40'000'000;  // 40 MHz. Lower to 20'000'000 if you see noise or garbage.

Adafruit_ST7789 tft(&SPI, PIN_TFT_CS, PIN_TFT_DC, PIN_TFT_RST);
GFXcanvas16 *frame = nullptr;  // 320 x 170 x 2 bytes = 106 KB, lives in PSRAM.

// Colours are 16-bit "RGB565": 5 bits red, 6 green, 5 blue. color565 converts from 0-255 values.
struct Palette {
  uint16_t ink, paper, grid, trace, accent, muted;
} pal;

void definePalette() {
  pal.paper = tft.color565(12, 18, 28);    // deep blue-black, like an oscilloscope screen
  pal.grid = tft.color565(30, 46, 66);     // faint graticule
  pal.trace = tft.color565(90, 230, 190);  // phosphor green-cyan
  pal.accent = tft.color565(255, 176, 60); // amber, for numbers
  pal.ink = tft.color565(230, 236, 245);   // near-white text
  pal.muted = tft.color565(120, 140, 165); // secondary text
}

void colourCheck() {
  const int16_t bar = kW / 3;
  tft.fillRect(0, 0, bar, kH, ST77XX_RED);
  tft.fillRect(bar, 0, bar, kH, ST77XX_GREEN);
  tft.fillRect(bar * 2, 0, kW - bar * 2, kH, ST77XX_BLUE);
  tft.setTextColor(ST77XX_WHITE);
  tft.setTextSize(2);
  tft.setCursor(30, 76);
  tft.print("RED   GREEN   BLUE");
  log_i("Colour check on screen. Left->right should read red, green, blue.");
  // If the screen is all white/black: check wiring and BLK. If the colours are inverted
  // (e.g. black background looks white), call tft.invertDisplay(false) after tft.init().
}

void drawGraticule(GFXcanvas16 &g) {
  for (int16_t x = 0; x < kW; x += 32) g.drawFastVLine(x, 34, kH - 34, pal.grid);
  for (int16_t y = 34; y < kH; y += 34) g.drawFastHLine(0, y, kW, pal.grid);
}

void drawFrame(GFXcanvas16 &g, uint32_t now, float fps) {
  g.fillScreen(pal.paper);

  // Header
  g.setTextSize(2);
  g.setTextColor(pal.ink);
  g.setCursor(8, 8);
  g.print("hello, bench");
  g.setTextSize(1);
  g.setTextColor(pal.muted);
  g.setCursor(196, 8);
  g.print("ESP32-S3 N16R8");
  g.setCursor(196, 20);
  g.printf("%.0f fps", fps);

  drawGraticule(g);

  // A travelling sine wave with a slower wobble on top, so it looks alive.
  const float t = now / 1000.0f;
  int16_t prevY = -1;
  for (int16_t x = 0; x < kW; x++) {
    float phase = x * 0.045f - t * 3.0f;
    float y = sinf(phase) * 40 * (0.7f + 0.3f * sinf(t * 0.7f)) + sinf(phase * 3.1f) * 6;
    int16_t py = 102 + static_cast<int16_t>(y);
    if (prevY >= 0) g.drawLine(x - 1, prevY, x, py, pal.trace);
    prevY = py;
  }

  // Uptime, bottom right, as hh:mm:ss
  uint32_t s = now / 1000;
  g.setTextColor(pal.accent);
  g.setTextSize(2);
  g.setCursor(196, kH - 22);
  g.printf("%02lu:%02lu:%02lu", static_cast<unsigned long>(s / 3600),
           static_cast<unsigned long>(s / 60 % 60), static_cast<unsigned long>(s % 60));
}

}  // namespace

void setup() {
  Serial.begin(115200);
  delay(1500);

  // Backlight first, so we can tell "screen dead" apart from "nothing drawn yet".
  pinMode(PIN_TFT_BL, OUTPUT);
  digitalWrite(PIN_TFT_BL, HIGH);

  SPI.begin(PIN_TFT_SCLK, -1 /* no MISO: the screen never talks back */, PIN_TFT_MOSI, PIN_TFT_CS);
  tft.init(170, 320);
  tft.setSPISpeed(kSpiHz);
  tft.setRotation(1);
  definePalette();
  log_i("Display ready: %dx%d over SPI at %lu MHz", tft.width(), tft.height(),
        static_cast<unsigned long>(kSpiHz / 1'000'000));

  colourCheck();
  delay(2500);

  frame = new GFXcanvas16(kW, kH);
  if (frame == nullptr || frame->getBuffer() == nullptr) {
    log_e("Could not allocate the %d-byte frame buffer. Is PSRAM enabled?", kW * kH * 2);
    return;
  }
  log_i("Frame buffer: %d KB, PSRAM free: %lu KB", kW * kH * 2 / 1024,
        static_cast<unsigned long>(ESP.getFreePsram() / 1024));
}

void loop() {
  if (frame == nullptr || frame->getBuffer() == nullptr) {
    delay(1000);
    return;
  }

  static uint32_t lastFrame = millis();
  static uint32_t lastLog = 0;
  static float fps = 0;

  uint32_t now = millis();
  float dt = (now - lastFrame) / 1000.0f;
  lastFrame = now;
  if (dt > 0) fps = fps * 0.9f + (1.0f / dt) * 0.1f;  // smoothed, so the number doesn't jitter

  drawFrame(*frame, now, fps);
  tft.drawRGBBitmap(0, 0, frame->getBuffer(), kW, kH);  // send the finished picture

  if (now - lastLog >= 5000) {
    lastLog = now;
    log_i("%.1f fps", fps);
  }
}

// The one place that says which wire goes where.
// Change a number here (or pass -DPIN_xxx=N as a build flag) and every lesson follows.
//
// Pins to keep away from on the ESP32-S3-N16R8:
//   0, 3, 45, 46   strapping pins: they decide how the chip boots
//   19, 20         native USB D- / D+
//   26-32          wired to the flash chip
//   33-37          wired to the octal PSRAM (that's the "R8" in N16R8)
//   43, 44         UART0 TX / RX: the serial monitor on the "COM" port
#pragma once

// On-board addressable RGB LED (WS2812). Most N16R8 DevKitC clones use 48;
// v1.1 boards use 38. If lesson 01 shows no colour, try 38.
#ifndef PIN_RGB
#define PIN_RGB 48
#endif

// The BOOT button already on the board. It only matters at power-on (hold it to enter flash mode);
// once our program runs, GPIO 0 is a normal input. Pressed = LOW. Used from lesson 03b.
#ifndef PIN_BOOT_BTN
#define PIN_BOOT_BTN 0
#endif

// Lesson 03b: external push button. GPIO 5 -> one leg, the diagonally opposite leg -> GND.
// The internal pull-up makes the pin read HIGH when up and LOW when pressed.
#ifndef PIN_BUTTON
#define PIN_BUTTON 5
#endif

// Lesson 02: external LED. GPIO 4 -> 220-330 ohm resistor -> LED long leg (+), short leg (-) -> GND.
#ifndef PIN_LED
#define PIN_LED 4
#endif

// Lesson 03: 1.9" ST7789 SPI display. These are the S3's native SPI2 (FSPI) pins, the fastest route.
// Module label -> ESP32-S3 pin
#ifndef PIN_TFT_SCLK
#define PIN_TFT_SCLK 12  // SCL / SCK / CLK
#endif
#ifndef PIN_TFT_MOSI
#define PIN_TFT_MOSI 11  // SDA / MOSI / DIN
#endif
#ifndef PIN_TFT_CS
#define PIN_TFT_CS 10    // CS
#endif
#ifndef PIN_TFT_DC
#define PIN_TFT_DC 9     // DC / RS / A0
#endif
#ifndef PIN_TFT_RST
#define PIN_TFT_RST 8    // RES / RST
#endif
#ifndef PIN_TFT_BL
#define PIN_TFT_BL 7     // BLK / BL / LED (backlight)
#endif

// RFID track: the RC522 board (MFRC522 chip) on the S3's second SPI bus (SPI3), so it never shares
// wires or timing with the screen on SPI2. The four SPI pins sit side by side on the left header
// in the same order as the module's pins: SDA, SCK, MOSI, MISO.
// Module label -> ESP32-S3 pin. 3.3V only: the MFRC522 is not 5 V tolerant.
#ifndef PIN_RFID_SS
#define PIN_RFID_SS 15    // SDA (in SPI mode this is chip select, NSS)
#endif
#ifndef PIN_RFID_SCK
#define PIN_RFID_SCK 16   // SCK
#endif
#ifndef PIN_RFID_MOSI
#define PIN_RFID_MOSI 17  // MOSI
#endif
#ifndef PIN_RFID_MISO
#define PIN_RFID_MISO 18  // MISO
#endif
#ifndef PIN_RFID_RST
#define PIN_RFID_RST 14   // RST (low = hard power-down)
#endif
#ifndef PIN_RFID_IRQ
#define PIN_RFID_IRQ 13   // IRQ (optional: -1 = not wired, the lab then polls)
#endif

// Sound track: the KY-037 microphone module (electret capsule + LM393 comparator + a blue trim pot).
// Power it from 3V3, never 5 V: its AO and DO outputs swing up to its supply, and the ESP32-S3 pins
// take 3.3 V at most. Module label -> ESP32-S3 pin.
//   AO must be an ADC1 pin (GPIO 1-10): ADC2 is busy while Wi-Fi is on. 6 = ADC1 channel 5.
//   DO is the comparator's yes/no output: any digital pin.
#ifndef PIN_MIC_AO
#define PIN_MIC_AO 6   // AO (analog: the microphone's voltage)
#endif
#ifndef PIN_MIC_DO
#define PIN_MIC_DO 21  // DO (digital: high = louder than the pot's threshold)
#endif

// Sound track, digital: the INMP441 MEMS microphone (I2S, 24-bit). VDD -> 3V3, GND -> GND,
// L/R -> GND (we read the left slot). Three wires in a row on the right header.
#ifndef PIN_I2S_MIC_SCK
#define PIN_I2S_MIC_SCK 40  // SCK (bit clock)
#endif
#ifndef PIN_I2S_MIC_WS
#define PIN_I2S_MIC_WS 41   // WS (word select: left/right)
#endif
#ifndef PIN_I2S_MIC_SD
#define PIN_I2S_MIC_SD 42   // SD (the data)
#endif

// Sound track, out loud: the MAX98357A I2S amplifier + a 4 ohm speaker on its screw terminal.
// VIN -> 5V (louder; 3V3 works, quieter), GND -> GND, GAIN and SD unconnected (9 dB, mono mix).
#ifndef PIN_I2S_SPK_BCLK
#define PIN_I2S_SPK_BCLK 39  // BCLK
#endif
#ifndef PIN_I2S_SPK_LRC
#define PIN_I2S_SPK_LRC 38   // LRC (word select)
#endif
#ifndef PIN_I2S_SPK_DIN
#define PIN_I2S_SPK_DIN 47   // DIN (the data)
#endif
